/* ------------------------------------------------------------------ */
/*  Compact university list — 1000+ universities with real GPS data    */
/*  Each entry is minimal; the generator in universities.ts expands    */
/*  them into full University objects with programs, videos, etc.       */
/* ------------------------------------------------------------------ */

export interface UniSeed {
  id: string;
  name: string;
  country: string;
  flag: string;
  city: string;
  continent: string;
  lat: number;
  lng: number;
  qsRanking: number;
  tuitionNumeric: number;
  tuition: string;
  type: "public" | "private";
  language: string;
  hasScholarship: boolean;
  acceptanceRate: number;
  ielts: string;
  toefl: string;
  sat: string;
  act: string;
  studentsCount: number;
  programsCount: number;
  deadline: string;
  employmentRate: number;
  livingCost: string;
  housingAvailable: boolean;
}

/* Helper to create compact entries */
function u(
  id: string, name: string, country: string, flag: string, city: string,
  continent: string, lat: number, lng: number, qs: number,
  tuitionNum: number, tuition: string, type: "public" | "private",
  language: string, scholarship: boolean, acceptance: number,
  ielts: string, toefl: string, sat: string, act: string,
  students: number, programs: number, deadline: string,
  employment: number, livingCost: string, housing: boolean,
): UniSeed {
  return {
    id, name, country, flag, city, continent, lat, lng,
    qsRanking: qs, tuitionNumeric: tuitionNum, tuition, type,
    language, hasScholarship: scholarship, acceptanceRate: acceptance,
    ielts, toefl, sat, act, studentsCount: students, programsCount: programs,
    deadline, employmentRate: employment, livingCost, housingAvailable: housing,
  };
}

